// Regenerates public/geo/*.json and src/app/denteus/regional/countries.ts from open datasets.
// Usage: npm i --no-save world-countries all-the-cities in a scratch directory, then
//   node tools/build-geo.mjs /path/to/scratch/node_modules
// The datasets are NOT dependencies of the app: only the generated files are shipped.
import { createRequire } from 'node:module';
import { mkdirSync, writeFileSync } from 'node:fs';
const root = process.argv[2];
if (!root) throw new Error('pass the node_modules directory');
const req = createRequire(root + '/x.js');
const countries = req('world-countries');
const cities = req('all-the-cities');

const phone = (c) => { const { root: r, suffixes } = c.idd; return !r ? '' : suffixes?.length === 1 ? r + suffixes[0] : r; };
const rows = countries.map((c) => [c.cca2, Object.keys(c.currencies ?? {})[0] ?? '', phone(c)]).sort((a, b) => a[0].localeCompare(b[0]));
writeFileSync('src/app/denteus/regional/countries.ts', `// Generated by tools/build-geo.mjs from world-countries (ODbL). Do not edit by hand.\n/** ISO 3166-1 alpha-2, ISO 4217 currency and international phone prefix, one row per country or territory. */\nexport const COUNTRY_ROWS = ${JSON.stringify(rows.map((r) => r.join('|')).join(';'))};\n`);

const by = new Map();
for (const c of cities) { if (!by.has(c.country)) by.set(c.country, []); by.get(c.country).push(c); }
mkdirSync('public/geo', { recursive: true });
let total = 0;
for (const [code, list] of by) {
  list.sort((a, b) => b.population - a.population);
  const seen = new Set(); const names = [];
  for (const c of list) { const k = c.name.toLowerCase(); if (!seen.has(k)) { seen.add(k); names.push(c.name); } }
  writeFileSync(`public/geo/${code}.json`, JSON.stringify(names)); total += names.length;
}
writeFileSync('public/geo/NOTICE.txt', 'City names: GeoNames (https://www.geonames.org), CC BY 4.0, via the all-the-cities package (places with 1000+ inhabitants).\nCountry index: world-countries (https://github.com/mledoze/countries), ODbL 1.0.\n');
console.log(rows.length, 'countries,', by.size, 'city files,', total, 'names');
